import json
import re
from difflib import get_close_matches
from html.parser import HTMLParser
from pathlib import Path
from typing import Dict, List, Optional, Tuple
from urllib.parse import unquote

import httpx
from pydantic import BaseModel

from openreward.environments import Environment, JSONObject, TextBlock, ToolOutput, tool


# ---------------------------------------------------------------------------
# Task definitions — loaded from tasks.json (generated by generate_tasks.py)
# ---------------------------------------------------------------------------

_TASKS_FILE = Path(__file__).parent / "tasks.json"

def _load_tasks() -> Dict[str, List[JSONObject]]:
    with open(_TASKS_FILE) as f:
        return json.load(f)

WIKI_TASKS = _load_tasks()

WIKIPEDIA_API = "https://en.wikipedia.org/w/api.php"

# Sections to strip from the end of articles (case-insensitive check)
_STOP_SECTIONS = {"see also", "references", "external links", "further reading", "notes", "bibliography", "sources"}


# ---------------------------------------------------------------------------
# Lightweight HTML-to-Markdown converter
# ---------------------------------------------------------------------------

class _WikiHTMLToMarkdown(HTMLParser):
    """Converts Wikipedia article HTML to markdown with inline wiki-links."""

    def __init__(self) -> None:
        super().__init__()
        self.output: List[str] = []
        self.links: Dict[str, str] = {}  # normalized_title -> canonical_title

        # State tracking
        self._skip_depth: int = 0  # > 0 means we are inside a tag to skip
        self._in_heading: bool = False
        self._heading_level: int = 0
        self._heading_text: str = ""
        self._current_link_title: Optional[str] = None
        self._current_link_text: str = ""
        self._stopped: bool = False  # True once we hit a stop-section heading
        self._in_sup: bool = False

        # Tags whose entire subtree we want to skip
        self._skip_tags = {"table", "figure", "style", "script"}

    # -- helpers --

    @staticmethod
    def _normalize(title: str) -> str:
        return title.strip().replace("_", " ").lower()

    def _is_wiki_link(self, href: str) -> Optional[str]:
        """Return the article title if *href* is an internal wiki link, else None."""
        if not href:
            return None
        if href.startswith("/wiki/"):
            raw = unquote(href[6:])
            # Exclude non-article namespaces
            if ":" in raw.split("#")[0]:
                prefix = raw.split(":")[0].lower()
                non_article = {
                    "file", "image", "category", "template", "wikipedia",
                    "help", "portal", "talk", "user", "special", "draft",
                    "mediawiki", "module", "book",
                }
                if prefix in non_article:
                    return None
            return raw.split("#")[0]  # strip anchors
        return None

    # -- parser callbacks --

    def handle_starttag(self, tag: str, attrs: List[Tuple[str, Optional[str]]]) -> None:
        if self._stopped:
            return

        attr_dict = dict(attrs)

        # Skip certain wrapper divs (infobox, navbox, sidebar, metadata, etc.)
        cls = (attr_dict.get("class") or "").lower()
        skip_classes = ("infobox", "navbox", "sidebar", "metadata", "mw-empty-elt",
                        "hatnote", "noprint", "toc", "mw-editsection", "reference",
                        "reflist", "thumb", "gallery", "mw-heading")
        if any(sc in cls for sc in skip_classes):
            self._skip_depth += 1
            return

        if tag in self._skip_tags:
            self._skip_depth += 1
            return

        if self._skip_depth > 0:
            self._skip_depth += 1
            return

        if tag == "sup":
            self._in_sup = True
            return

        if tag in ("h2", "h3", "h4"):
            self._in_heading = True
            self._heading_level = int(tag[1])
            self._heading_text = ""
            return

        if tag == "p":
            self.output.append("\n")
            return

        if tag == "br":
            self.output.append("\n")
            return

        if tag == "li":
            self.output.append("\n- ")
            return

        if tag == "b":
            self.output.append("**")
            return

        if tag == "i":
            self.output.append("*")
            return

        if tag == "a":
            href = attr_dict.get("href", "")
            title = self._is_wiki_link(href)
            if title:
                self._current_link_title = title
                self._current_link_text = ""
            return

    def handle_endtag(self, tag: str) -> None:
        if self._stopped:
            return

        if self._skip_depth > 0:
            self._skip_depth -= 1
            return

        if tag == "sup":
            self._in_sup = False
            return

        if tag in ("h2", "h3", "h4") and self._in_heading:
            self._in_heading = False
            heading = self._heading_text.strip()
            if heading.lower() in _STOP_SECTIONS:
                self._stopped = True
                return
            prefix = "#" * self._heading_level
            self.output.append(f"\n\n{prefix} {heading}\n\n")
            return

        if tag == "p":
            self.output.append("\n")
            return

        if tag == "b":
            self.output.append("**")
            return

        if tag == "i":
            self.output.append("*")
            return

        if tag == "a" and self._current_link_title is not None:
            title = self._current_link_title
            text = self._current_link_text.strip() or title
            self.output.append(f"[{text}]({title})")
            norm = self._normalize(title)
            self.links[norm] = title
            self._current_link_title = None
            self._current_link_text = ""
            return

    def handle_data(self, data: str) -> None:
        if self._stopped or self._skip_depth > 0 or self._in_sup:
            return

        if self._in_heading:
            self._heading_text += data
            return

        if self._current_link_title is not None:
            self._current_link_text += data
            return

        self.output.append(data)

    def get_markdown(self) -> str:
        text = "".join(self.output)
        # Collapse excessive blank lines
        text = re.sub(r"\n{3,}", "\n\n", text)
        return text.strip()


def _parse_wiki_html(html: str) -> Tuple[str, Dict[str, str]]:
    """Parse Wikipedia HTML into (markdown_text, {normalized_title: canonical_title})."""
    parser = _WikiHTMLToMarkdown()
    parser.feed(html)
    return parser.get_markdown(), parser.links


# ---------------------------------------------------------------------------
# Pydantic models
# ---------------------------------------------------------------------------

class ClickLinkInput(BaseModel, extra="forbid"):
    """Click a link on the current Wikipedia page to navigate to a new article."""
    link: str


class ViewPageInput(BaseModel, extra="forbid"):
    """View a specific page of the current Wikipedia article."""
    page: int


class TaskSpec(BaseModel):
    id: str
    start: str
    target: str


# ---------------------------------------------------------------------------
# Environment
# ---------------------------------------------------------------------------

class WikiGame(Environment):
    """Wikipedia Game: navigate from a start article to a target article by clicking links."""

    def __init__(self, task_spec: JSONObject, secrets: dict[str, str] = {}) -> None:
        super().__init__(task_spec)
        self.validated = TaskSpec.model_validate(task_spec)

        self.current_article: str = self.validated.start
        self.target_article: str = self.validated.target
        self.num_clicks: int = 0
        self.max_clicks: int = 20
        self.visited: List[str] = [self.validated.start]
        self.current_links: Dict[str, str] = {}  # normalized -> canonical
        self.current_pages: List[str] = []  # paginated content for current article

        self.client = httpx.AsyncClient(
            timeout=30.0,
            headers={
                "User-Agent": "WikiGameEnvironment/1.0 (https://openreward.org; wikigame@openreward.org)",
                "Api-User-Agent": "WikiGameEnvironment/1.0 (https://openreward.org; wikigame@openreward.org)",
                "Accept": "application/json",
            },
        )

    # -- Wikipedia helpers ------------------------------------------------

    @staticmethod
    def _normalize_title(title: str) -> str:
        return title.strip().replace("_", " ").lower()

    async def _fetch_page(self, title: str) -> Tuple[str, str, Dict[str, str]]:
        """Fetch a Wikipedia page.

        Returns (resolved_title, markdown_content, links_dict) where
        links_dict maps normalized titles to canonical titles.
        """
        params = {
            "action": "parse",
            "page": title,
            "prop": "text|links|displaytitle",
            "format": "json",
            "redirects": "true",
            "disabletoc": "true",
        }
        resp = await self.client.get(WIKIPEDIA_API, params=params)
        resp.raise_for_status()
        data = resp.json()

        if "error" in data:
            raise ValueError(f"Wikipedia API error: {data['error'].get('info', 'unknown')}")

        parse = data["parse"]
        resolved_title = parse.get("title", title)
        html = parse["text"]["*"]

        # Parse HTML to markdown + inline links
        markdown, inline_links = _parse_wiki_html(html)

        # Also add links from the structured links array (ns=0 only, existing)
        for link_entry in parse.get("links", []):
            if link_entry.get("ns") == 0 and "exists" in link_entry:
                canon = link_entry["*"]
                norm = self._normalize_title(canon)
                if norm not in inline_links:
                    inline_links[norm] = canon

        return resolved_title, markdown, inline_links

    def _find_link(self, query: str) -> Optional[str]:
        """Find a matching link on the current page. Returns canonical title or None."""
        norm = self._normalize_title(query)
        if norm in self.current_links:
            return self.current_links[norm]
        return None

    def _suggest_links(self, query: str, max_suggestions: int = 5) -> List[str]:
        """Suggest similar link titles for a failed match."""
        all_titles = list(self.current_links.values())
        return get_close_matches(query, all_titles, n=max_suggestions, cutoff=0.4)

    def _titles_match(self, a: str, b: str) -> bool:
        return self._normalize_title(a) == self._normalize_title(b)

    @staticmethod
    def _paginate(content: str, page_size: int = 8000) -> List[str]:
        """Split *content* into pages of roughly *page_size* chars, breaking at paragraph boundaries."""
        if len(content) <= page_size:
            return [content]

        pages: List[str] = []
        remaining = content
        while remaining:
            if len(remaining) <= page_size:
                pages.append(remaining)
                break
            # Try to break at a paragraph boundary
            cut = remaining[:page_size]
            break_at = cut.rfind("\n\n")
            if break_at < page_size // 2:
                # No good paragraph break — fall back to last newline
                break_at = cut.rfind("\n")
            if break_at < page_size // 4:
                # Still nothing — hard cut
                break_at = page_size
            pages.append(remaining[:break_at].rstrip())
            remaining = remaining[break_at:].lstrip("\n")
        return pages

    def _format_page(self, page_num: int) -> str:
        """Return the content for page *page_num* (1-indexed) with a page header."""
        total = len(self.current_pages)
        idx = page_num - 1
        header = f"[Page {page_num} of {total}]"
        footer = ""
        if page_num < total:
            footer = f"\n\n[Page {page_num} of {total} -- use view_page to see other pages]"
        return f"{header}\n\n{self.current_pages[idx]}{footer}"

    # -- Environment interface --------------------------------------------

    async def get_prompt(self) -> List[TextBlock]:
        resolved, content, links = await self._fetch_page(self.current_article)
        self.current_article = resolved
        self.current_links = links
        self.current_pages = self._paginate(content)
        self.visited = [resolved]

        page_content = self._format_page(1)

        prompt = (
            f"# Wikipedia Game\n\n"
            f"**Start:** {self.current_article}\n"
            f"**Target:** {self.target_article}\n\n"
            f"Navigate from the start article to the target article by clicking links on each page. "
            f"Each click costs one step. The game ends when you reach the target or after {self.max_clicks} clicks. "
            f"Your score is the negative number of clicks used (fewer is better).\n\n"
            f"**Tools:**\n"
            f"- `click_link(link=\"Article Title\")` - navigate to a linked article (costs 1 click)\n"
            f"- `view_page(page=N)` - view page N of the current article (free, no click cost)\n\n"
            f"---\n\n"
            f"## {self.current_article}\n\n"
            f"{page_content}"
        )
        return [TextBlock(text=prompt)]

    @tool
    async def click_link(self, params: ClickLinkInput) -> ToolOutput:
        """Click a link on the current Wikipedia page to navigate to a new article."""

        canonical = self._find_link(params.link)

        if canonical is None:
            suggestions = self._suggest_links(params.link)
            hint = ""
            if suggestions:
                hint = "\n\nDid you mean one of these?\n" + "\n".join(f"- {s}" for s in suggestions)
            return ToolOutput(
                metadata={
                    "error": "link_not_found",
                    "query": params.link,
                    "suggestions": suggestions,
                },
                blocks=[TextBlock(
                    text=f"Link \"{params.link}\" not found on the current page.{hint}"
                )],
                reward=0.0,
                finished=False,
            )

        # Valid link — navigate
        self.num_clicks += 1

        try:
            resolved, content, links = await self._fetch_page(canonical)
        except Exception as exc:
            # Network/API error — don't penalise, let the agent retry
            self.num_clicks -= 1
            return ToolOutput(
                metadata={"error": "fetch_failed", "detail": str(exc)},
                blocks=[TextBlock(text=f"Failed to fetch page \"{canonical}\": {exc}")],
                reward=0.0,
                finished=False,
            )

        self.current_article = resolved
        self.current_links = links
        self.current_pages = self._paginate(content)
        self.visited.append(resolved)

        base_metadata = {
            "num_clicks": self.num_clicks,
            "current_article": self.current_article,
            "target_article": self.target_article,
            "visited": self.visited,
        }

        # Check if target reached
        if self._titles_match(self.current_article, self.target_article):
            return ToolOutput(
                metadata={**base_metadata, "found_target": True},
                blocks=[TextBlock(
                    text=(
                        f"You reached the target article \"{self.target_article}\" "
                        f"in {self.num_clicks} click{'s' if self.num_clicks != 1 else ''}!\n\n"
                        f"Path: {' -> '.join(self.visited)}"
                    )
                )],
                reward=-self.num_clicks,
                finished=True,
            )

        # Check click limit
        if self.num_clicks >= self.max_clicks:
            return ToolOutput(
                metadata={**base_metadata, "found_target": False},
                blocks=[TextBlock(
                    text=(
                        f"Click limit reached ({self.max_clicks}). "
                        f"You did not reach \"{self.target_article}\".\n\n"
                        f"Path: {' -> '.join(self.visited)}"
                    )
                )],
                reward=-self.max_clicks,
                finished=True,
            )

        # Continue playing — show page 1 of the new article
        page_content = self._format_page(1)
        status = (
            f"Navigated to \"{self.current_article}\" "
            f"(click {self.num_clicks}/{self.max_clicks}). "
            f"Target: \"{self.target_article}\"\n\n"
            f"---\n\n"
            f"## {self.current_article}\n\n"
            f"{page_content}"
        )
        return ToolOutput(
            metadata={**base_metadata, "found_target": False},
            blocks=[TextBlock(text=status)],
            reward=0.0,
            finished=False,
        )

    @tool
    async def view_page(self, params: ViewPageInput) -> ToolOutput:
        """View a specific page of the current Wikipedia article (does not cost a click)."""
        total = len(self.current_pages)
        if params.page < 1 or params.page > total:
            return ToolOutput(
                metadata={"error": "invalid_page", "requested": params.page, "total_pages": total},
                blocks=[TextBlock(
                    text=f"Invalid page number {params.page}. This article has {total} page{'s' if total != 1 else ''} (1-{total})."
                )],
                reward=0.0,
                finished=False,
            )

        page_content = self._format_page(params.page)
        status = (
            f"## {self.current_article}\n\n"
            f"{page_content}"
        )
        return ToolOutput(
            metadata={
                "current_article": self.current_article,
                "page": params.page,
                "total_pages": total,
            },
            blocks=[TextBlock(text=status)],
            reward=0.0,
            finished=False,
        )

    # -- Task catalogue ---------------------------------------------------

    @classmethod
    def list_tasks(cls, split: str) -> List[JSONObject]:
        if split not in WIKI_TASKS:
            raise ValueError(f"Unknown split: {split}. Available: {list(WIKI_TASKS.keys())}")
        return WIKI_TASKS[split]

    @classmethod
    def list_splits(cls) -> list[str]:
        return list(WIKI_TASKS.keys())
